/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsDsTproverkau2eSign *dm_DsDsTproverkau2eSign_copy(const dm_DsDsTproverkau2eSign *d) {
    dm_DsDsTproverkau2eSign *r = dm_DsDsTproverkau2eSign_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsDsTproverkau2eSign_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dm_DsTproverkau2eSign_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsDsTproverkau2eSign_reindex(r);
    return r;
}
static dm_DsDsTproverkau2eSign *dm_DsDsTproverkau2eSign_mut(dm_DsDsTproverkau2eSign **pp) {
    dm_DsDsTproverkau2eSign *d = *pp;
    if (d->h.rc > 1) { dm_DsDsTproverkau2eSign *r = dm_DsDsTproverkau2eSign_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
